const fs = require('fs');
const path = require('path');
const wasmPath = path.join(__dirname, 'a1_program.wasm');
const bytes = fs.readFileSync(wasmPath);

const imports = {
  ux: {
    print_i32: (v) => { console.log('I32:' + v); },
    print_f64: (v) => { console.log('F64:' + v); },
    host_call4: (...a) => { console.log('host_call4', a); return 0; },
    host_call16: (...a) => { console.log('host_call16', a); return 0; },
  },
};

(async () => {
  try {
    const r = await WebAssembly.instantiate(bytes, imports);
    console.log('instantiated ok, calling MAIN...');
    const ret = r.instance.exports.MAIN();
    console.log('MAIN returned:', ret);
  } catch (e) {
    console.log('ERROR: ' + e.stack);
  }
})();

